function validate(input) {
  const [{ Movies = [], Users = [], MovieRating = [] }] = input;
  const unique = (rows, label, text) => {
    const ids = new Set(), texts = new Set();
    for (const [id, value] of rows) {
      if (id === null || value === null) return `Every ${label} needs an id and a ${text}.`;
      if (ids.has(id)) return `${label} id ${id} appears twice.`;
      // MySQL compares text without case, so names that differ only in case would collide.
      if (texts.has(String(value).toLowerCase())) return `${text} ${value} appears twice.`;
      ids.add(id); texts.add(String(value).toLowerCase());
    }
    return ids;
  };
  const movies = unique(Movies, 'movie', 'title');
  if (typeof movies === 'string') return movies;
  const users = unique(Users, 'user', 'name');
  if (typeof users === 'string') return users;
  const pairs = new Set();
  let february = false;
  for (const [movie, user, rating, day] of MovieRating) {
    if (!movies.has(movie)) return `A rating names unknown movie ${movie}.`;
    if (!users.has(user)) return `A rating names unknown user ${user}.`;
    if (pairs.has(`${movie}:${user}`)) return `User ${user} rates movie ${movie} twice.`;
    pairs.add(`${movie}:${user}`);
    if (rating === null) return 'Every rating needs a value.';
    if (day === null || !/^\d{4}-\d{2}-\d{2}$/.test(day) || Number.isNaN(Date.parse(`${day}T00:00:00Z`))) return `${day} is not a date.`;
    if (day.startsWith('2020-02-')) february = true;
  }
  if (!february) return 'At least one rating must be dated in February 2020.';
  return null;
}

