function generate(rand, size) {
  const small = size === 'small';
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const syllables = ['ka', 'lo', 'mi', 'ra', 'te', 'zu', 'an', 'bo'];
  const word = () => syllables[Math.floor(rand() * 8)] + syllables[Math.floor(rand() * 8)];
  // Small pools share prefixes and one title equals a user name, so tie-breaks and UNION ALL matter.
  const titles = small ? shuffle(['Avengers', 'Frozen 2', 'Frozen', 'Joker', 'Up']) : [];
  const names = small ? shuffle(['Daniel', 'Monica', 'Maria', 'James', 'Joker']) : [];
  const movieCount = small ? 1 + Math.floor(rand() * 4) : 300;
  const userCount = small ? 1 + Math.floor(rand() * 4) : 200;
  const Movies = [], Users = [], MovieRating = [];
  for (let id = 1; id <= movieCount; id++) Movies.push([id, small ? titles[id - 1] : `${word()} ${id}`]);
  for (let id = 1; id <= userCount; id++) Users.push([id, small ? names[id - 1] : `${word()} ${id}`]);
  const smallDates = ['2020-01-31', '2020-02-01', '2020-02-14', '2020-02-29', '2020-03-01', '2019-02-14'];
  const target = small ? 1 + Math.floor(rand() * 8) : 2000;
  const seen = new Set();
  for (let tries = 0; MovieRating.length < target && tries < target * 4; tries++) {
    const movie = 1 + Math.floor(rand() * movieCount), user = 1 + Math.floor(rand() * userCount);
    if (seen.has(`${movie}:${user}`)) continue;
    seen.add(`${movie}:${user}`);
    const day = small ? smallDates[Math.floor(rand() * smallDates.length)]
      : new Date(Date.UTC(2020, 0, 1) + Math.floor(rand() * 91) * 86400000).toISOString().slice(0, 10);
    MovieRating.push([movie, user, 1 + Math.floor(rand() * 5), day]);
  }
  if (!MovieRating.some(row => row[3].startsWith('2020-02-'))) MovieRating[0][3] = '2020-02-14';
  return [{ Movies, Users, MovieRating }];
}
